// Local cache and capability checks run before the standing-World poisons.
function occurrenceOwnerControls(owner:NativeAreaSceneOccurrences,foreign:OccHost){
 const input=owner.input;let checks=0;
 assert.equal(Object.hasOwn(freshSceneOccurrenceState(),'occHostObj'),false);
 assert.equal(Object.isFrozen(input),true);assert.equal(Object.isFrozen(owner.host),true);
 assert.equal(Object.keys(owner).includes('host'),false);assert.equal(Object.keys(owner).includes('input'),false);
 for(const key of Object.keys(input)){
  let reads=0;const candidate={...input};Object.defineProperty(candidate,key,{get(){reads++;throw Error('binding getter');}});
  assert.throws(()=>new NativeAreaSceneOccurrences(candidate),/own object binding/);assert.equal(reads,0);checks++;
  const inherited=Object.assign(Object.create({[key]:(input as any)[key]}),input);delete inherited[key];
  assert.throws(()=>new NativeAreaSceneOccurrences(inherited),/own object binding/);checks++;
 }
 for(const key of ['scene','geometry']){assert.throws(()=>new NativeAreaSceneOccurrences({...input,[key]:{}} as any),/same mutable/);checks++;}
 assert.throws(()=>new NativeAreaSceneOccurrences({...input,state:{...input.state,occHostObj:foreign} as any}),/cache cannot transfer/);checks++;
 let reads=0;const state={...input.state};Object.defineProperty(state,'occHostObj',{get(){reads++;return foreign;}});
 assert.throws(()=>new NativeAreaSceneOccurrences({...input,state}),/cache cannot transfer/);assert.equal(reads,0);checks++;
 const original=Object.getOwnPropertyDescriptor(input.state,'occHostObj');
 try{
  Object.defineProperty(input.state,'occHostObj',{configurable:true,writable:true,value:foreign});
  const local=owner.occHost();assert.notEqual(local,foreign);assert.equal(owner.occHost(),local);checks++;
  Object.defineProperty(input.state,'occHostObj',{configurable:true,get(){throw Error('late carried getter');}});
  assert.equal(owner.occHost(),local);assert.equal(local.zoneLevel(),input.scene.zone.level);checks++;
  const another=new NativeAreaSceneOccurrences({...input,state:freshSceneOccurrenceState()});assert.notEqual(another.occHost(),local);checks++;
 }finally{if(original)Object.defineProperty(input.state,'occHostObj',original);else delete (input.state as any).occHostObj;}
 for(const [provider,key]of [[input.geometry,'markDoodadsChanged'],[input.geometry,'clampPos'],[input.population,'createMonster'],[input.population.input.sources.ambient,'weightedPick'],[owner,'massOccurrenceSpawnTable']] as const){
  const old=Object.getOwnPropertyDescriptor(provider,key);let calls=0;
  try{Object.defineProperty(provider,key,{configurable:true,value:function(this:unknown,...args:unknown[]){assert.equal(this,provider);assert.deepEqual(args,['selected',7]);calls++;return 91;}});
   const selected=(owner.host as any)[key];Object.defineProperty(provider,key,{configurable:true,value(){throw Error('late method selected');}});
   assert.equal(selected('selected',7),91);assert.equal(calls,1);checks++;
  }finally{if(old)Object.defineProperty(provider,key,old);else delete (provider as any)[key];}
 }
 return checks;
}

// Actual classic cached view: lazy native method selection, mutable roots and
// no reflective census pin. The positive foreign-target control prevents a
// vacuous pass if ordinary controller ownership stops working.
let occurrenceCachedSelections=0;
withSeededRandom(61997,()=>{
 const world:any=makeSimWorld('warrior',61997),actor=world.createMonster('zombie',10,'enemy');
 world.actors=[world.player,actor];const owned=new Map([['occurrence-cache-witness',actor]]);
 assert.equal(massDormancyPins(world,owned).has(actor),false);
 const host=world.nativeSceneOccurrenceHost();assert.equal(host,world.nativeSceneOccurrenceHost());
 assert.equal(Object.getOwnPropertyDescriptor(world,'nativeSceneOccurrenceView')?.enumerable,false);
 assert.equal(Object.keys(world).includes('nativeSceneOccurrenceView'),false);
 const changed=[actor,world.player];world.actors=changed;assert.equal(host.actors,changed);
 const cached=world.occHost();assert.equal(world.occHost(),cached);
 const zone=world.zone;world.zone={...zone,level:17};assert.equal(cached.zoneLevel(),17);world.zone=zone;
 assert.equal(massDormancyPins(world,owned).has(actor),false);
 world.player.aiTargetId=actor.id;assert.equal(massDormancyPins(world,owned).has(actor),true);world.player.aiTargetId=-1;
 for(const name of ['markDoodadsChanged','massOccurrenceSpawnTable','weightedPick','createMonster','clampPos']){
  const prior=Object.getOwnPropertyDescriptor(world,name),calls:any[]=[],argument={name};
  try{
   Object.defineProperty(world,name,{configurable:true,writable:true,value:function(this:unknown,...args:unknown[]){calls.push(['old',this===world,args]);return 'old';}});
   const selected=host[name];
   Object.defineProperty(world,name,{configurable:true,writable:true,value:function(this:unknown,...args:unknown[]){calls.push(['new',this===world,args]);return 'new';}});
   assert.equal(selected(argument),'old');assert.equal(host[name](argument),'new');
   assert.equal(calls[0][2][0],argument);assert.deepEqual(calls,[['old',true,[argument]],['new',true,[argument]]]);occurrenceCachedSelections++;
  }finally{if(prior)Object.defineProperty(world,name,prior);else delete world[name];}
 }
});
assert.equal(occurrenceCachedSelections,5);
console.log('PASS actual World occurrence cache',occurrenceCachedSelections,'method selections and true controller pin control');
